import {roleFor} from './npc-routines.js?v=5.38';
export const CIVILIAN_STYLES=['Household cook','Young reader','Stonemason','Seedkeeper','Field healer','Ferryman','Teacher','Merchant','Archivist','Mechanic','Innkeeper','Watchkeeper','Young runner','Older craftsman','Older neighbour','Trail guide'];
const named={Mara:0,Nell:1,Father:13,Dara:4,Hesper:8,Corin:5};
export function civilianStyle(o,person){if(!person||o.rivalId||['Sable','Iona','Rook','Brass','Riven','Mira','Veyr'].includes(person.name))return null;if(named[person.name]!==undefined)return named[person.name];if(o.member===2)return ['Pip','Kit','Soli','Wren','Fin','Lark'].includes(o.name)?12:1;const role=roleFor(o)+' '+(o.label||'');const classes=[[/seed|garden|graft|flower|herb|grazier/,3],[/healer|medic|nurse/,4],[/ferry|dock|water|spill|rain|level/,5],[/lens|letter|archive|tally|paper|signal|reader|diarist/,8],[/repair|mechanic|patch|case|glass|polish|rope|chimney/,9],[/cook|oven|baker|soup|portion|steward/,0],[/inn|shelter/,10],[/mason|stone|roof/,2],[/teacher|weav|mend|seam|blanket/,6],[/guide|refuge|runner|carrier|porter/,15]];const found=classes.find(([p])=>p.test(role));if(found)return found[1];return ({shop:7,mentor:6,transport:5,guide:15,aid:4})[o.type]??(o.family?(o.member===0?14:13):11);}
/** The roots stay on the ground. Sway comes from a slight upper-body lean, never bobbing the complete sprite. */
export function civilianStance(o,time,state,x,y){const moving=!!o.path?.length&&state.mode==='field',phase=(o.name||'').split('').reduce((n,v)=>n+v.charCodeAt(0),0)*.17,near=Math.hypot(state.x-x,state.y-y)<3;return {moving,flip:moving?o.facing===1:near?state.x>x:false,lean:moving?Math.sin(time*6+phase)*.012:Math.sin(time*.9+phase)*.0025};}
export function drawCivilian(r,o,person,x,y,time,state){const id=civilianStyle(o,person);if(id===null||!r.assets.npcs)return false;const c=r.ctx,child=[1,12].includes(id),pose=civilianStance(o,time,state,x,y);c.save();c.translate(x*48,y*48);c.transform(1,0,pose.lean,1,0,0);const painted=civilianImage(r,id,civilianPalette(o,person));if(painted){const scale=Math.min(48*(child?1.05:1.35)/painted.width,48*(child?.94:1.26)/painted.height);if(pose.flip)c.scale(-1,1);c.drawImage(painted,-painted.width*scale/2,-painted.height*scale,painted.width*scale,painted.height*scale);}else r.atlas('npcs',id%4,Math.floor(id/4),0,0,48*(child?1.05:1.35),48*(child?.94:1.26),pose.flip);c.restore();return true;}

/** Named story people keep their authored colors; residents get repeatable textile dyes. */
export function civilianPalette(o,person){if(named[person.name]!==undefined||o.rivalId)return 0;const key=(o.name||person.name||'')+':'+(o.family?.id||'')+':'+(o.member??'');let seed=2166136261;for(const ch of key)seed=Math.imul(seed^ch.charCodeAt(0),16777619)>>>0;return 1+seed%7;}
const civilianPaint=new WeakMap();
function civilianImage(r,id,palette){const image=r.assets.npcs,b=r.bounds?.npcs?.[id];if(!b||!palette||typeof document==='undefined')return null;let variants=civilianPaint.get(image);if(!variants){variants=new Map();civilianPaint.set(image,variants);}const key=id+':'+palette;if(variants.has(key))return variants.get(key);const a=document.createElement('canvas');a.width=b.w;a.height=b.h;const c=a.getContext('2d');c.drawImage(image,b.x,b.y,b.w,b.h,0,0,b.w,b.h);const dyes=['','hue-rotate(24deg) saturate(.75)','hue-rotate(-26deg) saturate(.82)','hue-rotate(49deg) saturate(.62)','hue-rotate(-44deg) saturate(.66)','saturate(.46) brightness(.91)','saturate(.81) brightness(1.08)','hue-rotate(12deg) saturate(.6) brightness(.88)'];c.save();c.beginPath();c.rect(0,Math.round(b.h*.36),b.w,b.h);c.clip();c.clearRect(0,0,b.w,b.h);c.filter=dyes[palette];c.drawImage(image,b.x,b.y,b.w,b.h,0,0,b.w,b.h);c.restore();variants.set(key,a);return a;}
